def bold(f):
    return lambda: '<b>' + f() + '</b>'

def italic(f):
    return lambda: '<i>' + f() + '</i>'

@bold
@italic
def title():
    return 'Atölye'

print(title())

def log_call(function):
    def wrapper(*args, **kwargs):
        print('call', function.__name__, args, kwargs)
        return function(*args, **kwargs)
    return wrapper

@log_call
def full_name(first, last, country='Türkiye'):
    return f'{first} {last} ({country})'

print(full_name('Ada', 'Kaya', country='Finland'))

