from functools import wraps

def careful(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper

@careful
def greet(name):
    return 'Merhaba ' + name

print(greet.__name__, greet('Ada'))

